# Query: list powered-on vms with >8 vcpus and memory over 16gb, show name, host and project owner, newest 10
import sys
sys.path.insert(0, "/home/nutanix/cluster/bin")
import env
import gflags
gflags.FLAGS([])
from google.protobuf.text_format import Merge
from insights_interface.insights_interface_pb2 import GetEntitiesWithMetricsArg
from insights_interface.insights_interface import InsightsInterface, InsightsInterfaceError

insights_interface = InsightsInterface("127.0.0.1", "2027")
arg = GetEntitiesWithMetricsArg()
query = '''
query {
  entity_list { entity_type_name: "vm" }
  where_clause {
    and_list {
      comparison_expr { lhs { leaf { column: "power_state" } } operator: kEQ rhs { leaf { value { str_value: "on" } } } }
      comparison_expr { lhs { leaf { column: "num_vcpus" } } operator: kGT rhs { leaf { value { int64_value: 8 } } } }
      comparison_expr { lhs { leaf { column: "mem_gb" } } operator: kGT rhs { leaf { value { int64_value: 16 } } } }
    }
  }
  group_by {
    raw_columns { column: "vm_name" }
    raw_columns { column: "host" }
    raw_columns { column: "mem_gb" }
    raw_sort_order { sort_column: "create_time_usecs" sort_order: kDescending }
    raw_limit { limit: 10 }
  }
  query_name: "auto_query"
}
'''
Merge(query, arg)
try:
    ret = insights_interface.GetEntitiesWithMetrics(arg)
    print(ret)
except InsightsInterfaceError as ex:
    print("Error Message: " + ex.message)
